pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Classes based on divisibility by common item sizes (10..80 multiples).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, best outcome
    } else if pr < 10 {
        40.0 // dead space below minimum item size
    } else if pr % 10 == 0 {
        -15.0 // aligns with standard item granularity
    } else if pr % 20 == 0 || pr % 40 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -5.0
    } else {
        3.0
    };
    score += class_bonus;

    // Fractional capacity thresholds: how full will the bin be?
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 { score -= 12.0; }
    else if fill > 0.6 { score -= 6.0; }
    else if fill < 0.3 { score += 8.0; }

    // Integer division threshold on next_item_size vs post_residual:
    // does the lookahead item fit in the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chains nicely with next item
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 4.0; }
        } else if next_item_size <= bin_residual {
            // next item would rather go in this bin's current space; placing here
            // with bad leftover hurts
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // no good harmonic fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 15.0 * pressure - 20.0 * progress;
        if item_size > 60 { score -= 10.0; }
        if next_item_size > 0 && next_item_size > item_size { score += 8.0; }
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit the smallest plausible item are wasted.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward: prefer bins where the item occupies a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage opening/keeping many bins when mean residual is large.
    if open_bins_count > 1 {
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (mean residual small or item nearly fills a fresh bin).
    if bin_residual == bin_capacity {
        let fresh_util = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * fresh_util;
        if mean_residual < item_size as f64 {
            score -= 30.0; // open bins are too full -> new bin is good
        } else {
            score += 35.0; // existing bins have room -> penalize new bin
        }
    }

    // Mild late-stream conservatism: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

