    // Open-bin pressure: discourage proliferating bins, but allow it when
    // this is the only fitting bin (last chance) or the fit is exact.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when few bins open, or item is large
