            }
        } else {
            score += 60.0 + 40.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 45.0;
        }
        if post_residual == 0 {
