        // If next item is large and this bin would hold both, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild preference for fuller bins overall (waste minimization).
    score -= (bin_residual - post_residual) as f64 / bin_capacity as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), non-linearly scaled
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight packing matters less; later, dead space is heavily penalized
    let tightness_weight = 0.5 + 3.0 * progress * progress;
    score += tightness_weight * norm_pr * norm_pr * cap * 0.1;

    // Reward filling the bin well, smoothly increasing over the stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + progress);

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let fit_gap = (norm_pr - norm_next).abs();
        let kernel = 1.0 / (1.0 + 12.0 * fit_gap * fit_gap);
        score -= 6.0 * kernel * (0.4 + 0.6 * progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize bins far from the mean residual (fragmentation pressure), smoothly
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress * norm_pr;

    // New-bin candidate: encourage opening fresh bins only when the current item
    // leaves a very awkward residual in existing bins
    let fresh = (bin_residual == bin_capacity) as i32 as f64;
    score += fresh * (4.0 - 6.0 * norm_item * (1.0 - norm_item)) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes of post_residual.
    // Class 0: perfect fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space penalty grows superlinearly for small unusable leftovers.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // tiny slivers are nearly unusable
        }
        // Harmonic class via modulo: residuals divisible by small item sizes
        // (10..=20) are more likely to be filled later -> reward.
        let class_bonus = if post_residual % 10 == 0 {
            30.0
        } else if post_residual % 20 == 0 {
            22.0
        } else if post_residual % 5 == 0 {
            12.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Lookahead coupling: if the next item fits exactly into post_residual,
        // strongly favor this bin.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 250.0;
            } else if next_item_size < post_residual {
                let slack = post_residual - next_item_size;
                score -= 40.0 - slack as f64 * 0.5; // tighter next-fit is better
                // Harmonic pair: next item lands on a class boundary too
                if slack % 10 == 0 {
                    score -= 15.0;
                }
            } else {
                // next item cannot follow here; mild penalty scaled by gap
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0
            - 40.0 * progress
            - mean_residual * 0.4
            - (post_residual as f64) * 0.2;
        // If many open bins can't take the item, opening fresh is more acceptable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is already below the mean (consolidation).
    score += (mean_residual - bin_residual as f64).max(0.0) * -0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 25.0;
    }

    // Reward bins whose residual stays large enough to host a future item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * progress;

    // New-bin candidate: only attractive when the item is huge relative to residual
    // or fits would create dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
