pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest item (<= 10) is worthless.
    if post_residual < 10 {
        score -= 25.0; // perfect closure of a bin
    } else if post_residual < 20 {
        score -= 12.0; // near-closed bin
    } else if post_residual < 30 {
        score -= 4.0; // still potentially usable
    }

    // Penalize large post_residual proportionally to how far it is from
    // typical item sizes, scaled by stream progress (late in stream,
    // leftover space is less likely to be filled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 + 25.0 * progress);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward; if it doesn't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Many fitting bins: mild preference for tighter fits already
        // handled; slight penalty to spread usage too thin.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Global state coupling: prefer bins whose residual deviates from the
    // mean in a useful direction — filling bins below mean residual keeps
    // larger residuals available for bigger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 4.0;
    }

    // Mild load-balancing across many open bins late in the stream.
    score += (open_bins_count as f64).sqrt() * (post_residual as f64) * 0.05 * progress;

    // New-bin candidate: only attractive when nothing else fits well —
    // penalize it when a fitting bin exists with decent tightness.
    if bin_residual == bin_capacity {
        if fitting_bins_count >= 1 && post_residual < bin_capacity {
            score += 40.0;
        }
        // Empty bin is fine early when stream is long (investment).
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Reward tight fits: quadratic penalty on wasted space, scaled by progress
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * cap * (0.5 + 1.5 * progress);

    // Reward filling bins well early (keeps many small-residual bins around)
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Lookahead: bonus if next item fits in the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - pr / cap) * (nxt / cap);
        } else {
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open and this creates tiny residual
    if pr > 0.0 && pr < 10.0 {
        score += 2.0 + 0.1 * open_bins_count as f64;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so it's
    // chosen only when all open bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify leftover space ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect fit or tiny dead space -> strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Class 2: leftover large enough to host common small item classes.
    // Item sizes are 1..100; define harmonic anchors via integer division.
    let pr_u = post_residual;
    let small_anchor = pr_u / 4;          // quarter-class anchor
    let mid_anchor = pr_u / 2;            // half-class anchor
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr_u {
            // next item fits here: reward proportionally to how snugly
            let snug = (pr_u - n) as f64;
            score -= 60.0 + 40.0 * (1.0 - snug / cap);
            // extra reward if next item exactly matches a harmonic anchor
            if n == small_anchor || n == mid_anchor || pr_u % n == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this leftover: penalize dead space
            score += 25.0 + 0.5 * pr;
            // modulo penalty: leftover that misses next item by a sliver
            let gap = n - pr_u;
            if gap <= 10 {
                score += 40.0; // near-miss is worst case
            }
        }
    }

    // Class 3: residual fraction classes (eighths of capacity)
    let eighth = (pr / (cap / 8.0)).floor() as i64;
    // mid-class leftovers (2..5 eighths) are reusable; tiny or huge differ
    match eighth {
        0 => score += 10.0,          // nearly full: fine, but keep small
        1 => score -= 15.0,          // small reusable gap
        2..=5 => score -= 10.0,      // moderate reusable gap
        6 => score += 5.0,           // awkward large gap
        _ => {}
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the current bin's post_residual would be badly stranded.
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a decent fit, better than stranding.
        score = cap * 0.45
            + if next_item_size > 0 && next_item_size <= bin_capacity {
                0.0
            } else {
                0.0
            }
            - if post_residual == bin_capacity && item_size >= 60 { 20.0 } else { 0.0 };
        // large items prefer fresh bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 {
            score -= 30.0 * progress;
        }
    }

    // Mild penalty for leaving residual far from mean (fragmentation spread)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are unusable for future items (min item = 1,
    // but statistically small gaps waste capacity). Penalize gaps in [1, 20] heavily.
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 3.0;
    }

    // Perfect fit is excellent: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: discourage spreading across many bins; encourage closing bins out.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., current fit is poor) or when item is large and fits alone-ish.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 25.0 && item_size < 60;
        if poor_fit && fitting_bins_count > 0 {
            // Opening a new bin is only good if it avoids a really bad fit elsewhere;
            // make it moderately attractive but not dominant.
            score -= 5.0;
        } else {
            // Prefer reusing open bins in general.
            score += 20.0;
        }
        // Large items starting fresh bins is fine (they dominate a bin anyway).
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below average, it's a good
    // consolidation target; if far above average, deprioritize.
    let dev = (post_residual as f64) - mean_residual;
    score += dev * 0.4;

    // Mild stream-progression pressure: later in stream, be more conservative about
    // leaving dead space (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the pair
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - pair_waste * 0.8;
        } else {
            // next item won't fit: penalize wasted residual that becomes dead space
            score += (post_residual as f64) * 0.5;
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a genuinely good idea
    if bin_residual == bin_capacity {
        // base penalty so existing bins are usually preferred
        score += 70.0;
        // opening a new bin is attractive only if no good fit exists and the next
        // item would pair well with a full capacity residual
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair_waste = (bin_capacity - next_item_size) as f64;
            if pair_waste < 5.0 {
                score -= 55.0;
            }
        }
        // late in the stream, avoid opening bins for small leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer minimal post residual.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit bonus (dead space <= 5).
    if post_residual > 0 && post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual exactly, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // chain fit is fine, slight reward proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving large gaps next item can't use
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last chance: only fitting bin — strong preference to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than average are more precious;
    // wasting them on loose fits is bad.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.3;

    // Penalize creating tiny unusable gaps relative to smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (spread load);
    // late in stream, consolidate to avoid opening near-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing fits are poor (large post residual) or
        // when many bins are open late (consolidation pressure pushes against new bins).
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit && progress < 0.7 {
            score -= 80.0;
        } else {
            score += 60.0 + 40.0 * progress;
        }
        // Never open a new bin for a small item if any open bin fits well.
        if item_size <= 50 && open_bins_count > 0 {
            score += 30.0;
        }
    }

    // Fragmentation guard: avoid putting items into bins where leftover becomes
    // awkwardly small but nonzero, unless it's the last chance.
    if post_residual > 0 && post_residual < 20 && fitting_bins_count > 1 {
        score += 10.0;
    }

    // Slight preference to fill fuller bins first (residual smaller = better),
    // scaled by number of alternatives.
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.35 * progress) + 18.0 * x * x * (1.0 - x);

    // Penalty for large dead space that scales super-linearly as stream progresses
    // (dead space becomes less recoverable later).
    score += 25.0 * progress * x * x * x;

    // Smooth interaction: reward fills that leave residual close to a likely next fit.
    let nx = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = (x - nx).abs();
        score -= 12.0 * (1.0 - gap.min(1.0)) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - progress * 0.3);
    } else {
        score += 3.0 / fitting_bins_count as f64;
    }

    // Mild penalty for deviating from mean residual: keep bin residuals balanced.
    score += 0.08 * (pr - mean_residual).abs();

    // Slight preference against accumulating many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftovers.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Harmonic class logic on post_residual: classify leftover space.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes
    match class {
        0 => score -= 30.0,               // near-perfect fit (0..9 leftover)
        1 => score -= 12.0,               // good fit
        2 => score += 5.0,                // mediocre
        3 => score += 10.0,               // awkward leftover ~30-39
        4 => score += 2.0,                // ~40-49 still usable for medium items
        _ => score += 0.0,
    }

    // Modulo arithmetic: residuals divisible by 10 pair well with 10-multiple items.
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Penalize leftovers that no typical next item can use (< smallest plausible item).
    if pr < 10 && pr > 0 {
        score += 25.0; // dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to overshoot class
            score += ((next_item_size - pr) / 20) as f64 * 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 0 {
            // only prefer a new bin if all open bins would leave terrible leftovers
            let best_possible_waste = (bin_capacity as f64 - item_size as f64);
            let open_bin_penalty = mean_residual * 0.5 + open_bins_count as f64 * 2.0;
            score += 60.0 + open_bin_penalty - best_possible_waste * 0.3;
        } else {
            // no open bin fits: new bin is necessary; reward slightly by progress
            score -= 20.0 - 10.0 * progress;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.3 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
