    // Lookahead: reward bins whose leftover can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the fit elsewhere is poor
    // (large item, big residual wasted). Penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (item_size as f64);
        if fitting_bins_count > 0 {
