        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving a gap just below the next item's size.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 15.0 {
                score += 12.0 * (1.0 - gap / 15.0);
