}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), smoothly scaled.
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // late in the stream, tight fits matter more; dead space penalized superlinearly.
    let t = progress;
    let pr_norm = pr / cap; // 0..1
    let coupling = (pr_norm * pr_norm) * (0.5 + 1.5 * t * t) * cap;
    score += coupling;

    // Reward bins that are nearly full (small residual) with a smooth cubic term.
    let fill = 1.0 - pr_norm;
    score -= (fill * fill * fill) * (10.0 + 30.0 * t);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * t;
    }

    // Lookahead: if next item fits exactly in post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64) as f64;
        score -= (1.0 - diff / cap) * (8.0 + 12.0 * t);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by wasted potential.
        let waste = next_item_size as f64 / cap;
        score += waste * (5.0 + 10.0 * t);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average),
    // smoothly penalizing deviation.
    score += ((pr - mean_residual) / cap).abs() * (2.0 + 6.0 * t) * ((pr - mean_residual) / cap).signum();

    // New-bin candidate: penalize opening a new bin, more so when open bins exist
    // and progress is late; smooth in open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 + 40.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
