    // Base: strongly penalize residual, but with harmonic (modular) shaping.
    score = pr * (1.0 + 0.5 * frac);

    // Dead-space classes: residuals that almost nothing can fit are terrible.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
