    // Harmonic bands: classify post_residual by integer division thresholds.
    let band = post_residual / 25; // 0,1,2,3
    score += match band {
        0 => -40.0, // 0..24: sweet spot
        1 => 0.0,   // 25..49: ok
        2 => 15.0,  // 50..74: mediocre
        _ => 35.0,  // 75..99: wasteful unless new bin
    };

    // Perfect fits / near-perfect fits get big reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // typical item sizes (multiples of 10 common in many streams).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 10.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline score = full capacity, adjusted by stream
    // position and how crowded the current set is. Prefer new bins early or
    // when open bins are already tight.
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if mean_residual < 15.0 {
            score -= 15.0; // existing bins nearly full -> new bin attractive
        }
    }

    // Mild crowding pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual alignment: prefer bins whose residual is below average
    // (tighter bins get priority).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
