    // and still leave a useful remainder.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 340.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            let mut chain_bonus = 45.0 * (1.0 - after_next as f64 / cap);
