            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        // Penalize residuals in the awkward mid-range that rarely fits typical
        // items, pushing packing toward tighter fills.
