            let mismatch = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - mismatch / cap).min(1.0) * (1.0 - progress);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

