                score += 14.0 * (dead_ratio - 0.3);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() as u32 <= 4 && post_residual >= next_item_size {
                score -= 8.0;
            }
            // NEW: when many bins are already open, opening yet another one
            // fragments the packing — dampen the fresh-bin attraction.
            if open_bins_count > 6 {
                score += 6.0 * ((open_bins_count - 6).min(10) as f64);
            }
        } else {
            score += 60.0 + 40.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 45.0;
        }
