        if mid_frag && !(next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3) {
            score += 7.0 * (0.6 - fill_frac);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

