        }
        if post_residual == 0 {
            score += 1800.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // Near-closed bins that cannot host the next item: consolidate them.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    // Small residual trap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Items 1..=100: a leftover is "dead" if nothing typical can use it.
        // Penalize tiny gaps quadratically.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 30 {
            score += (30 - post_residual) as f64 * 1.5;
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 200.0;
        }
        // Leftover that exactly fits the lookahead item is great.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 120.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else {
        score -= 200.0;
    }

    // Reward using nearly-full bins (tight fits) beyond raw post_residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading into new bins;
    // a fresh empty bin candidate should only win when open-bin fits are bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open bins count and mean residual.
        score += 80.0 + open_bins_count as f64 * 10.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.8;
        // Exception: if item is large relative to typical residual, new bin may be fine.
        score -= (item_size as f64) * 0.3;
    } else {
        // Mild preference for bins with small residual (compact packing).
        score += (bin_residual as f64) * 0.05;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 25.0;
    } else {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
