            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() as u32 <= 4 && post_residual >= next_item_size {
                score -= 8.0;
            }
            // NEW: when the fresh bin's leftover cannot host the next item at
            // all, opening it fragments the stream — dampen the opening bias
            // proportionally to the stranded dead space.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
