}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(3);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a residual that can never fit the next item
        if post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Penalize dead space: residuals too small to ever be useful (min item 1, but waste below ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // open new bin early when many items remain and open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && progress < 0.5 {
            score -= 10.0;
        }
    }

    // Mild preference for filling larger items into fuller bins
    score += (item_size as f64 / bin_capacity as f64) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post-residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space: residuals below smallest plausible item are nearly useless.
    if post_residual < 10 {
        score -= 25.0; // perfect closure bonus
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead (k=2): if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
