            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Global state coupling: many open bins with low mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual);
    score -= 2.0 * pressure.min(50.0);

    // Dynamic time horizon: early in the stream, be liberal about opening new bins
