    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress); // early: new bins cheap
        score += 10.0 * progress;         // late: new bins expensive
    }

    // Prefer bins whose residual is close to the mean (balanced packing) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // Mild preference for fuller bins overall.
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used;

    score
}

