            score -= 8.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 18.0 * norm_post * norm_post * (0.5 + prog2) - 10.0 * norm_post * (1.0 - prog3);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 22.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: reward if next item fits the post-residual, smooth polynomial
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = norm_next / (norm_post + 1e-9);
        score -= 14.0 * (fit_frac * (2.0 - fit_frac)) * (1.0 - progress * 0.5);
    } else if next_item_size > post_residual {
        score += 6.0 * norm_next * (0.3 + progress);
    }

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count <= 1 {
        score -= 9.0 * (1.0 - norm_post) * (1.0 + progress);
    } else {
        let fb = fitting_bins_count as f64;
        score += 2.5 * (fb - 1.0).min(5.0) / 5.0;
    }

    // Mean residual coupling: penalize if bin residual far below mean (fragmented bin)
    let mean_norm = mean_residual / bin_capacity as f64;
    let dev = norm_post - mean_norm;
    score += 5.0 * dev * dev * (0.5 + progress);

    // Mild penalty on opening new bins late in stream when open bins exist
    if bin_residual == bin_capacity {
        score += (3.0 + 10.0 * progress) * (open_bins_count as f64).max(1.0).ln();
    }

    score
}

