pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: items of size 1..=100 partition
    // the capacity into residue classes mod 25 (quarter-capacity harmonics).
    // Residuals that are "harmonic" (multiples of 25 or tiny) are reusable,
    // so reward them; awkward mid-band residuals are penalized.
    let pr = post_residual;
    let harm = pr % 25;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score += 25.0; // dead space below min item size
    } else if harm == 0 {
        score -= 18.0; // quarter-capacity aligned residual
    } else if pr <= 34 {
        // small residuals can absorb the common small items (1..=34)
        score -= 8.0;
    } else {
        // mid-band waste: penalize by distance to nearest harmonic class
        let dist = harm.min(25 - harm) as f64;
        score += 0.35 * dist;
    }

    // Lookahead coupling: reward if next item fits the post residual
    // (chained placement), penalize if next item is nearly the residual
    // (fragile single-slot fit).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
