    // is large and no open bin offers a tight fit.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let tightness = (bin_capacity - item_size) as f64;
        score = 40.0 + 0.5 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    } else {
        // tightness of the current fit: exact fills rewarded
        let slack = (bin_residual - item_size) as f64;
        score -= 0.4 * (bin_capacity as f64 - slack) / bin_capacity as f64;
    }

    // Stream progression: early on, be more willing to open bins (spread);
    // late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new {
        score -= 10.0 * (1.0 - progress);
    }

    // Crowding: many open bins with high mean residual -> discourage
    // leaving another large residual behind.
    if mean_residual > 40.0 && !is_new {
        score += 0.1 * (mean_residual - 40.0);
    }

    score
}

