            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Small-but-maybe-usable gaps (11..=25) get a milder penalty scaled by
    // how close they are to being truly dead.
    else if post_residual > 10 && post_residual <= 25 {
        score += 0.6 * (25 - post_residual) as f64;
    }

    // Reward near-perfect fills (exact or within 2 units).
    if post_residual <= 2 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, penalize the leftover gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        } else if post_residual >= next_item_size {
            score -= 0.25 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins over spawning new ones.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: make the empty bin attractive only when it enables a
    // clean split for the current + next item, otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
    }

    // Mild preference for filling bins that are already well depleted.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Stream progression: later in the stream, tighten up and avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
