pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post residual) is better.
    score = post_residual as f64 * 1.0;

    // --- Aggressive 2-step lookahead ---
    if next_item_size > 0 {
        // Perfect chaining: next item exactly fills the post residual.
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here: penalize dead space, worse if very small.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 * 0.5 {
                score += 25.0;
            } else {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Compare post residual against mean residual across open bins.
    // Leaving more than the mean residual wastes capacity relative to others.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins could fit, unless the item
    // is large and a fresh bin gives near-perfect packing.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 20.0 * tightness;
        } else {
            score += 15.0;
