            }
            if dead_ratio > 0.5 {
                score -= 22.0 * (dead_ratio - 0.5);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 2.0 {
                score -= 26.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
                score += 14.0 * (dead_ratio - 0.3);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() as u32 <= 4 && post_residual >= next_item_size {
                score -= 8.0;
            }
            // REFINED: when many open bins still have ample room, opening a
            // new bin should be less attractive unless the fit is excellent.
            if open_bins_count > 4 && dead_ratio > 0.35 {
                score += 10.0 + 2.0 * (open_bins_count.min(12) as f64);
            }
        } else {
            score += 60.0 + 40.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 45.0;
        }
        if post_residual == 0 {
            score += 1500.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > 0 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
        // NEW: when multiple bins can host the item, weight tightness of fit
        // more strongly to consolidate fills and reduce residual variance.
        if fitting_bins_count > 3 && post_residual > 0 {
            score += 3.0 * (post_residual as f64 / cap);
        }
        // NEW: mild reward for placing into bins whose leftover will land in
        // the "hostable" band (>= next item) versus the dead zone below it.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable slots"
    let r = post_residual % 10;
    let dead = (r != 0 && post_residual < 10) as f64;
    score += dead * 30.0;

    // Reward post_residuals that are multiples of 10 (classic bin capacity fractions)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect harmonic match
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            // penalize leaving awkward remainders
            let nr_class = nr % 10;
            score += (nr_class as f64) * 0.6;
            if nr < 10 { score += 12.0; }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on post_residual vs half capacity
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 4.0; // bin still flexible
    } else if post_residual <= bin_capacity / 10 {
        score += 10.0; // nearly full: good closure, but only if item fits — small bonus
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when mean residual is fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += fragmentation * 0.3;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0 * (1.0 - progress); // early stream, open fresh bin
        } else {
            score += 8.0; // default: prefer existing bins
        }
    }

    // Mild penalty for opening bins when many already open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

