pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space: small post_residual that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard-to-fill zone
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.6;
        } else {
            // Next item won't fit here; penalize wasting post-residual below next item size
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Slight preference for new bins early in the stream, tight packing later
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
        score += 30.0 - 20.0 * progress;
        // But if no open bin fits, opening new bin is necessary (handled by fitting count)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Penalize opening new bins when few bins are open and residual is plentiful
    if bin_residual == bin_capacity && mean_residual > 40.0 {
        score += 15.0;
    }

    score
}

