    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 1.5 * progress * norm_pr + 0.8 * progress * progress * (1.0 - norm_pr));

    // Dead-space penalty: quadratic in tiny post-residuals, stronger late in stream
    let dead = if norm_pr < 0.2 {
        (norm_pr - 0.2).powi(2) * (1.0 + 2.0 * progress) * cap
    } else {
        0.0
    };

