    let nxt = next_item_size as f64 / cap;
    let look = if next_item_size > 0 && next_item_size <= post_residual {
        -1.2 * nxt * (1.0 - progress) * (1.0 - norm_pr)
    } else if next_item_size > post_residual {
        0.5 * nxt * norm_pr
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last = if fitting_bins_count == 1 { -2.0 * (1.0 + progress) } else { 0.0 };

    // Slight preference for consolidating into fewer bins
    let spread = (bin_residual as f64 - mean_residual) / cap * 0.3;

    let mut score = poly * cap * 0.5 + dead + look + last + spread;
    // New-bin candidate: keep it slightly penalized unless post-residual is large
    if bin_residual == bin_capacity {
        score += 0.6 * (1.0 - norm_item) * (1.0 - progress);
    }
    score
}

