            // Reward opening a fresh bin whose leftover exactly equals a
            // plausible near-half split, enabling clean two-item fills.
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() as u32 <= 4 && post_residual >= next_item_size {
                score -= 8.0;
            }
            // NEW: sharpen the poor-fit trigger — when the dead space would be
            // very large (>40%), open a new bin even slightly later in the
            // stream, since huge dead space is the dominant waste source.
            if dead_ratio > 0.4 && progress < 0.92 {
                score -= 15.0 * (dead_ratio - 0.4);
