            score += 5.0 * (1.0 - progress);
        }
        // Strong reward for near-exact fills, scaled by how full the bin
        // already is — reinforces the compaction direction.
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        // Mid-large leftovers on half-full bins indicate fragmentation.
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        // When few bins can host the item, strongly prefer the tightest
        // fit to avoid scattering items across many partially-filled bins.
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // When the next item cannot fit anywhere in this bin's leftover
        // but the current item nearly empties it, add a small compaction nudge
        // proportional to fill level to consolidate near-closed bins first.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
        // NEW: prefer bins whose post-residual stays divisible-friendly for
        // small items — a leftover that is itself a plausible item size is
        // far more likely to be exactly filled by a later small item.
        if post_residual >= 3 && post_residual <= 20 && (post_residual as f64) <= mean_residual {
            score -= 4.0;
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fits rewarded
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic classes: bucket post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (pr / (cap / 4.0)).floor() as i32; // 0..4 harmonic class
    score += 8.0 * quarter as f64;

    // Dead-space penalty: residuals too small for typical items (modular thresholds)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: favor residuals divisible by common item classes
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 / (1.0 + slack as f64);
            // harmonic class of leftover after next item
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot follow here; penalize small post_residual
            score += 6.0;
        }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer only when current fit is poor
    if bin_residual == bin_capacity {
        score += 5.0;
        if fit_ratio < 0.6 {
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size <= bin_capacity / 2 {
            score -= 8.0;
        }
