            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
                score += 14.0 * (dead_ratio - 0.3);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() as u32 <= 4 && post_residual >= next_item_size {
                score -= 8.0;
            }
            // NEW: prefer opening a fresh bin when the current item is large
            // relative to capacity AND existing bins are scarce — placing big
            // items in a fresh bin preserves small residuals elsewhere.
            if item_size as f64 > cap * 0.5 && open_bins_count <= 4 {
                score -= 12.0;
            }
