    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = (norm_pr - nxt).max(0.0);
        score -= 20.0 * fit_next * (1.0 - fit_next);
        if norm_pr < nxt {
            score += 15.0 * (nxt - norm_pr);
        }
