    // Mild preference for consolidating bins when many are open
    score += 2.0 * open_bins_count as f64 * norm_pr;

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - progress) + 25.0;
    }

    score
}

