pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Class bins into harmonic residual classes: [0], (0,10], (10,25], (25,50], (50,100]
    // Tight fits (post_residual == 0) are perfect: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 25 {
        score -= 20.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        // large leftover: penalize dead space that only big items can use
        score += 10.0 * post_frac;
    }

    // Integer division thresholds: post_residual divisible by common item sizes
    // means a future item can exactly fill it.
    for d in [10u32, 20, 25, 50] {
        if post_residual >= d && post_residual % d == 0 {
            score -= 15.0;
            break;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
