            if open_bins_count > 6 && dead_ratio > 0.35 {
                score += 12.0 * (dead_ratio - 0.35);
            }
            // NEW: a fresh bin whose leftover exactly equals the mean
            // residual suggests a well-matched split — slight extra pull.
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() <= 3.0 {
                score -= 6.0;
            }
        } else {
            // Late stream or good fits available: discourage new bins.
            score += 60.0 + 40.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 45.0;
        }
        if post_residual == 0 {
            score += 1500.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        // Penalize residuals in the awkward mid-range that rarely fits
        // typical items, pushing packing toward tighter fills.
        if post_residual > 12 && post_residual < 25 && next_item_size > 0 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        // Strong reward for near-exact fills, scaled by how full the bin
        // already is — reinforces the compaction direction.
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        // Mid-large leftovers on half-full bins indicate fragmentation.
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        // When few bins can host the item, strongly prefer the tightest
        // fit to avoid scattering items across many partially-filled bins.
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // NEW: scarcity-weighted tightness — when only one bin fits the
        // item, take it almost regardless of fit quality to avoid
        // forcing a bin split later.
        if fitting_bins_count == 1 && post_residual > 0 {
            score -= 14.0;
        }
        // NEW: prefer bins whose leftover after placement stays out of the
        // awkward mid-band (13–24), which rarely hosts future items.
        if post_residual >= 13 && post_residual <= 24 {
            score += 7.0 * (1.0 - progress);
        }
        // When the next item cannot fit anywhere in this bin's leftover
        // but the current item nearly empties it, add a small compaction nudge
        // proportional to fill level to consolidate near-closed bins first.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual: small leftover space is good
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: quadratic reward for tight fits
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 8.0;
    // Cubic term penalizes large dead space super-linearly
    score += pr_norm * pr_norm * pr_norm * 12.0;

    // Stream progress interaction: later in stream, value tight packing more
    let tight_reward = (1.0 - pr_norm) * (1.0 - pr_norm) * progress * 10.0;
    score -= tight_reward;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = 1.0 - ((pr - ni) / cap);
            score -= fit_quality * fit_quality * 15.0 * (0.5 + 0.5 * progress);
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            score += ((ni - pr) / cap) * 6.0;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that are relatively full already
        score += (mean_residual - pr) * 0.3;
    }

    // Mild penalty for opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let escape = (pr_norm * pr_norm) * 25.0 * (1.0 - progress);
        score += 5.0 + escape;
    }

    // Smooth open-bin pressure: many open bins -> encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 2.0;

    score
}

