                score -= 30.0;
            } else if gap < 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // existing residuals are small (mean_residual low) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        let mut new_bin_score = waste * 0.6;
        // Early stream: prefer filling open bins to build density.
        new_bin_score += 25.0 * (1.0 - progress);
        // If open bins are nearly full on average, opening a fresh bin is fine.
        new_bin_score -= (mean_residual / cap).max(0.0) * 20.0;
        // If item barely fits anywhere, opening a bin is acceptable.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // Large items pair better with a fresh bin.
        if item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // Mild fragmentation penalty relative to mean residual: choosing bins far below
    // mean residual concentrates waste.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
