                    chain_bonus += 10.0 * (1.0 - (after_third - next_item_size) as f64 / cap);
                }
            }
            // NEW: scale chain bonus by scarcity of fitting bins.
            if fitting_bins_count <= 4 {
                chain_bonus *= 1.0 + 0.08 * (4 - fitting_bins_count) as f64;
            }
            score -= chain_bonus;
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            let soft = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 0.55 * waste * (0.5 + 0.5 * soft);
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 4 {
            score += 18.0;
        }
    }

    // Tightness preference, stronger with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * 0.35 * (0.5 + progress);

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual * 0.8;
        let dead_ratio = post_residual as f64 / cap;
        let poor_fit = dead_ratio > 0.24;
        if (poor_fit || large_item) && progress < 0.84 {
            score -= 95.0 + 32.0 * (1.0 - progress) + 28.0 * dead_ratio;
            if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 1.3 {
                score -= 20.0;
            }
            if dead_ratio > 0.5 {
                score -= 22.0 * (dead_ratio - 0.5);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 2.0 {
                score -= 26.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            // NEW: reward fresh bins whose leftover nearly equals the next
            // item (clean two-item split), enabling exact pair packing.
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
                score -= 8.0;
            }
            // Push back on fresh bins whose dead space falls in the
            // awkward mid-band where few items fit.
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
                score += 14.0 * (dead_ratio - 0.3);
            }
        } else {
            score += 60.0 + 45.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 240.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 50.0;
        }
        if post_residual == 0 {
            score += 1800.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // NEW: compaction nudge for near-closed bins the next item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    // Small residual trap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Classes based on divisibility by common item sizes (10..80 multiples).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, best outcome
    } else if pr < 10 {
        40.0 // dead space below minimum item size
    } else if pr % 10 == 0 {
        -15.0 // aligns with standard item granularity
    } else if pr % 20 == 0 || pr % 40 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -5.0
    } else {
        3.0
    };
    score += class_bonus;

    // Fractional capacity thresholds: how full will the bin be?
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 { score -= 12.0; }
    else if fill > 0.6 { score -= 6.0; }
    else if fill < 0.3 { score += 8.0; }

    // Integer division threshold on next_item_size vs post_residual:
    // does the lookahead item fit in the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chains nicely with next item
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 4.0; }
        } else if next_item_size <= bin_residual {
            // next item would rather go in this bin's current space; placing here
            // with bad leftover hurts
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // no good harmonic fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 15.0 * pressure - 20.0 * progress;
        if item_size > 60 { score -= 10.0; }
        if next_item_size > 0 && next_item_size > item_size { score += 8.0; }
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
