pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else if post_residual < 10 {
        score += 200.0; // unusable tiny gap: heavy penalty
    } else if post_residual < 20 {
        score += 80.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only allow opening a new bin when it is genuinely attractive,
    // e.g. current item plus lookahead would leave a clean large residual.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 90.0; // room for the next item too: new bin is good
        }
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead synergy: residual after placement that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 {
        score += 10.0; // lookahead can't use this residual
    }

    // Prefer bins whose residual is close to mean (avoid fragmenting outliers),
    // but reward using the tightest bin (small bin_residual) when it fits.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
