                chain_bonus += 6.0 * (1.0 - (after_next as f64 - 8.0) / 12.0);
            }
            if fitting_bins_count <= 2 {
                chain_bonus += 12.0 * (3.0 - fitting_bins_count as f64);
            }
            // Deeper lookahead: two-item chain leaving room for a third.
            if after_next >= next_item_size {
                let after_third = after_next - next_item_size;
                if after_third <= 2 {
                    chain_bonus += 14.0;
                } else if after_third == next_item_size {
                    chain_bonus += 18.0;
                } else if after_third >= next_item_size {
                    // Triple-chain trajectory: fully packed multi-item fill.
                    chain_bonus += 10.0 * (1.0 - (after_third - next_item_size) as f64 / cap);
                }
            }
            // Scale chain bonus by scarcity of fitting bins.
            if fitting_bins_count <= 4 {
