}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 10.0 * (1.0 - ((pr - nx) / cap).abs()) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr * norm_pr;

    // New-bin candidate handling: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Mean residual deviation coupling
    score += 3.0 * (pr - mean_residual) / cap * (pr - mean_residual) / cap * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly rewarded.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space avoidance: unusable small gaps are penalized (refined curve).
    if post_residual > 0 && post_residual <= 5 {
        score -= 50.0 - 4.0 * post_residual as f64;
    } else if post_residual > 5 && post_residual < 12 {
        score += 55.0 * (12.0 - post_residual as f64) / 12.0;
    }
    if post_residual >= 12 {
        score -= 9.0;
    }

    // Lookahead chain scoring: reward residuals that can host the next item
    // and still leave useful space afterwards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            let mut chain_bonus = 40.0 * (1.0 - after_next as f64 / cap);
            if after_next <= 5 {
                chain_bonus += 55.0;
            }
            if after_next >= next_item_size.min(50) {
                chain_bonus += 15.0;
            }
            if fitting_bins_count <= 2 {
                chain_bonus += 10.0 * (3.0 - fitting_bins_count as f64);
            }
            if after_next >= next_item_size {
                chain_bonus += 20.0;
            }
            if after_next > 0 && after_next <= 8 {
                chain_bonus += 16.0 * (1.0 - after_next as f64 / 8.0);
            }
            // Deeper lookahead: ideal 3-item fill trajectory.
            if after_next >= next_item_size {
                let after_third = after_next - next_item_size;
                if after_third <= 2 {
                    chain_bonus += 12.0;
                }
                if after_third >= next_item_size {
                    chain_bonus += 10.0 * (1.0 - (after_third - next_item_size) as f64 / cap);
                }
            }
            // Scale chain bonus by global scarcity of fitting bins.
            if fitting_bins_count <= 4 {
                chain_bonus *= 1.0 + 0.08 * (4 - fitting_bins_count) as f64;
            }
            // NEW: extra reward when the leftover after the next item is
            // either tiny (near-closed) or large enough for another mid item,
            // pushing residual distribution toward extremes.
            if after_next > 0 && (after_next <= 3 || after_next >= next_item_size.min(60)) {
                chain_bonus += 8.0;
            }
            score -= chain_bonus;
        } else {
            // Post-residual too small for the next item: penalize by waste.
            let waste = next_item_size as f64 - post_residual as f64;
            let soft = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 0.5 * waste * (0.5 + 0.5 * soft);
