    // common item-size classes (multiples of 10) and small-item sizes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward post_residuals that are exactly usable by a future item:
    // perfect fit (0) is best, small unusable slivers are penalized.
    if pr == 0 {
        score -= 60.0;
    } else if pr < 10 {
        // dead space below minimum item size
        score += (10 - pr) as f64 * 1.5;
    }

    // Harmonic class: post_residual divisible by 10 aligns with typical sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 10 != 0 {
        // distance to nearest multiple of 10 -> fragmentation penalty
        let d = (pr % 10).min(10 - pr % 10) as f64;
        score += d * 0.8;
    }

    // Does next_item_size fit into the post_residual? Strong lookahead reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (next_item_size as f64 / cap) * 10.0;
            // exact harmonic chain: post_residual is a multiple of next size
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many alternatives -> be pickier about waste
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.2;
    }

    // Relative tightness of the fit
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Prefer filling bins below mean residual (balance avoidance of many
    // half-empty bins): a bin with residual near mean_residual is neutral,
