    let resid_frac = bin_residual as f64 / cap;
    score -= (resid_frac - mean_residual / cap).abs() * 5.0;

    // Late in the stream, consolidate aggressively (fewer leftover bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // New-bin candidate (empty bin): penalize so it's only chosen when
    // every open bin scores worse (i.e., all fits are terrible).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    score
}

