            // NEW: prefer fresh bins whose dead space can absorb the next item
            // with near-zero waste (exact chain), scaled by item size.
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain_waste = post_residual - next_item_size;
                if chain_waste <= 6 {
