    // General small-gap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: this bin can host the next item too.
            let chain_slack = post_residual - next_item_size;
            // Reward perfect or near-perfect chaining.
            if chain_slack == 0 {
                score -= 60.0;
            } else {
                score -= 25.0 - (chain_slack as f64 / bin_capacity as f64) * 25.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving awkward space.
            let gap = next_item_size - post_residual;
            // Small gap = dead space that likely never gets used.
            if gap <= 10 {
                score += 15.0 + gap as f64;
            } else {
                score += 5.0 + (gap as f64 / bin_capacity as f64) * 10.0;
            }
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // --- Relative residual coupling ---
    // Bins with residuals far below the mean are "scarce large spaces";
    // using them for a tight fit is valuable. Bins far above mean are
    // already fragmented; filling them is cheap.
    let resid_f = bin_residual as f64;
    let rel = resid_f - mean_residual;
    if rel > 0.0 {
        // This bin has more space than average: spending it is less costly.
        score -= rel * 0.15;
    } else {
        // Below-average space: penalize wasting it unless fit is very tight.
        score += (-rel) * 0.10 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        // If we reject this bin, a new bin opens; strongly favor using it
        // unless the fit would be terrible.
        score -= 12.0;
        if post_residual > bin_capacity / 2 {
            // Very loose fit in the only fitting bin: still better than a new bin
            // usually, but soften the bonus.
            score += 6.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening it.
        score = (bin_capacity - item_size) as f64 + 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a new bin makes sense if it can chain the next item too.
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        // If many open bins already exist, discourage yet another bin.
        score += open_bins_count as f64 * 0.8;
        // If no other bin fits, opening is mandatory-ish; make it competitive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // --- Fragmentation guard ---
    // Penalize leaving residuals in the awkward 1..10 range (hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

