pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small unusable" classes are rewarded (dead space sealed).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual <= 10 -> essentially perfect packing.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    }

    // Integer-division classes on post_residual: multiples of 10 are
    // reusable slots (items >= 10), so leftover exactly in {10,20,...}
    // keeps future modularity.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual > 0 {
        // awkward leftover: penalize by how far from a multiple of 10
        let dist = (post_residual % 10).min(10 - post_residual % 10);
        score += dist as f64 * 0.8;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            score -= (20.0 - (chain as f64).min(20.0)) * 0.6;
        } else {
            // next item cannot use this residual at all: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (high post_residual waste) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let waste_vs_best = pr - mean_residual.max(0.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin is high; relax slightly as stream grows.
        score += 55.0 - 10.0 * progress;
        // If the mean residual of open bins is large (poor global fit),
        // opening fresh is less bad.
        if mean_residual > 0.5 * cap {
            score -= 20.0;
        }
        if waste_vs_best > 30.0 {
            score -= 10.0;
        }
        // Avoid opening bins early when few bins exist and fit is easy.
        if open_bins_count < 3 && progress < 0.2 {
            score += 15.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 12.0;
    } else if fill > 0.7 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1100.0;
    }
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0 - 4.0 * post_residual as f64;
    } else if post_residual > 5 && post_residual < 12 {
        score += 55.0 * (12.0 - post_residual as f64) / 12.0;
    }
    if post_residual >= 12 {
        score -= 9.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 340.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            let mut chain_bonus = 45.0 * (1.0 - after_next as f64 / cap);
            if after_next <= 5 {
                chain_bonus += 60.0;
            }
            if after_next >= next_item_size.min(50) {
                chain_bonus += 15.0;
            }
            if fitting_bins_count <= 2 {
                chain_bonus += 12.0 * (3.0 - fitting_bins_count as f64);
            }
            if after_next >= next_item_size {
                chain_bonus += 22.0;
                // deeper lookahead: chain a third item
                let after_third = after_next - next_item_size;
                if after_third <= 2 {
                    chain_bonus += 12.0;
                }
                if after_third >= next_item_size {
                    chain_bonus += 10.0 * (1.0 - (after_third - next_item_size) as f64 / cap);
                }
            }
            if after_next == next_item_size {
                chain_bonus += 40.0;
            }
            if after_next > 0 && after_next <= 8 {
                chain_bonus += 18.0 * (1.0 - after_next as f64 / 8.0);
            }
            if after_next <= 2 {
                chain_bonus += 12.0;
            }
            // scarcity scaling
            if fitting_bins_count <= 4 {
                chain_bonus *= 1.0 + 0.08 * (4 - fitting_bins_count) as f64;
            }
            score -= chain_bonus;
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            let soft = 1.0 / (1.0 + fitting_bins_count as f64);
            score += 0.55 * waste * (0.5 + 0.5 * soft);
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 4 {
            score += 18.0;
        }
    }

    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.3;

    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual * 0.8;
        let dead_ratio = post_residual as f64 / cap;
        let poor_fit = dead_ratio > 0.24;
        if (poor_fit || large_item) && progress < 0.84 {
            score -= 90.0 + 30.0 * (1.0 - progress) + 28.0 * dead_ratio;
            if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 * 1.3 {
                score -= 20.0;
            }
            if dead_ratio > 0.5 {
                score -= 22.0 * (dead_ratio - 0.5);
            }
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 2.0 {
                score -= 26.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
                score += 14.0 * (dead_ratio - 0.3);
            }
        } else {
            score += 60.0 + 40.0 * progress;
        }
        if item_size <= 50 && open_bins_count > 0 {
            score += 35.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 220.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 45.0;
        }
        if post_residual == 0 {
            score += 2000.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        if post_residual > 12 && post_residual < 25 && next_item_size > 0 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        // near-exact fill reward scaled by fullness
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        // fragmentation penalty on half-empty bins with big leftovers
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        // scarce fitting bins: prefer tightest fit
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // consolidate near-closed bins when next item can't fit there
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 4.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit: always strongly preferred.
    if post_residual == 0 {
        score -= 15.0;
    }

    if post_residual > 0 {
        // Lookahead coupling: shape the leftover so the known next item can use it.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 8.0; // leftover exactly consumed by next item
            } else if post_residual >= next_item_size {
                score -= 2.0; // leftover still usable for next item
            } else {
                score += 6.0; // leftover is dead for the known future
            }
        }

        // Strict dead-space avoidance: small nonzero gaps on existing bins
        // are effectively unusable -> graded + flat penalty.
        // (A fresh bin with a small leftover is nearly full, not dead.)
        if !is_new_bin && (post_residual as f64) < 10.0 {
            let r = post_residual as f64;
            score += 30.0 + 50.0 * (1.0 - r / 10.0);
        }
    }

    if is_new_bin {
        if open_bins_count == 0 || fitting_bins_count == 0 {
            // Forced opening: guarantee the new bin wins.
            score -= 1000.0;
        } else {
            // Open-bins pressure: with many open bins or late in the stream,
            // opening yet another bin fragments capacity -> penalize.
            score += 3.0 * open_bins_count as f64 + 10.0 * progress;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: this is the only open bin that fits, strongly favor it
        // over opening a new bin (unless dead-space penalties dominate).
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
