            }
            // Fresh bin chaining the next item almost perfectly: exact two-item packing.
            if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 2.0 {
                score -= 26.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            // Near-half split enabling a clean two-item fill.
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
                score -= 8.0;
            }
            // Push back on fresh bins with dead space in the awkward mid-band.
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
