            score += 35.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score += 240.0;
        }
        if progress > 0.8 && open_bins_count > 3 {
            score += 50.0;
        }
        if post_residual == 0 {
            score += 1800.0;
        }
    } else {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        if fill_frac > 0.7 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if fill_frac > 0.85 && post_residual > 0 {
            score -= 5.0;
        }
        // Residual hosting the next item while staying compact afterwards.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) < mean_residual * 0.45 {
            score -= 9.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64 - next_item_size as f64) <= 2.0 {
            score -= 7.0;
        }
        // Penalize awkward mid-range residuals unusable by the next item.
        if post_residual > 12 && post_residual < 25 && next_item_size > post_residual {
            score += 5.0 * (1.0 - progress);
        }
        // Strong reward for near-exact fills on well-loaded bins.
        if post_residual > 0 && post_residual <= 2 && fill_frac > 0.6 {
            score -= 12.0 * fill_frac;
        }
        // Fragmentation penalty: mid-large leftovers on half-full bins.
        if post_residual > 25 && fill_frac < 0.5 {
            score += 4.0 * (0.5 - fill_frac);
        }
        // Tightest fit preference when choices are scarce.
        if fitting_bins_count <= 3 && post_residual > 0 {
            score -= 6.0 * (1.0 - post_residual as f64 / cap);
        }
        // Compaction nudge for nearly-closed bins.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fill_frac > 0.9 {
            score -= 10.0 * (fill_frac - 0.9);
        }
    }

    // Small residual trap penalty.
    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when fits are scarce or residual is huge.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 3.0 } else { 1.0 };
        let pressure = (mean_residual - (item_size as f64)) / cap;
        score = cap * 0.55 * scarcity - 40.0 * pressure.max(0.0);
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 15.0; // fresh bin can host next item too
        }
        return score;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 45.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 20.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here: penalize dead space relative to mean residual
            score += 8.0 * ((post_residual as f64) / mean_residual.max(1.0)).min(3.0);
        }
    }

    // Last chance: strongly prefer using the sole fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild waste penalty proportional to post residual vs mean.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    score
}

