                score -= 26.0;
            }
            // Fresh bin whose leftover tightly chains the next item.
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
                score -= 18.0;
            }
            // Avoid awkward mid-band dead space on fresh bins.
            if dead_ratio > 0.3 && dead_ratio < 0.45 {
                score += 14.0 * (dead_ratio - 0.3);
            }
            // Near-half split enabling clean two-item fills.
            if next_item_size > 0 && post_residual >= next_item_size && ((post_residual as f64 - next_item_size as f64).abs() as u32) <= 4 {
                score -= 8.0;
            }
        } else {
