    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to strongly prefer small leftovers.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize new-bin candidate unless the item is large and would leave a useful gap.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Large items opening a fresh bin is fine (they need room for future small items).
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
        // Late in the stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 * (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
    } else {
        // Reward using an existing bin, more so when few bins fit the item (last chance).
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
        // Prefer bins whose residual is close to the item (best-fit refinement).
        score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

        // Lookahead: if the next item fits the post-residual well, reward this placement.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            } else {
                score += 3.0;
            }
        }

        // Coupling with global state: if mean residual is high, encourage consolidation
        // into existing bins rather than spreading.
        let mean_r = mean_residual.max(0.0);
        if (bin_residual as f64) > mean_r {
