}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly damped so it doesn't dominate everything
    let mut score = pr * (0.8 + 0.4 * norm_pr);

    // Non-linear polynomial coupling of residual tightness with stream progress:
    // early on, prefer larger post_residual (save big gaps? no — actually prefer tight fits),
    // later, tight fits matter more (waste compounds).
    let tightness = 1.0 - norm_pr;
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 30.0 * tightness * tightness * (0.5 + progress_poly);

    // Penalize residuals that are small but non-zero (dead space) with a cubic term
    if pr > 0.0 {
        let dead = norm_pr * (1.0 - norm_pr);
        score += 20.0 * dead * dead * (1.0 - progress);
    }

    // Perfect fit bonus (smooth via polynomial)
    let perfect = (pr == 0.0) as i32 as f64;
    score -= 15.0 * perfect;

    // Lookahead: reward post_residual that can still fit the next item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let fits_next = ((pr >= nx) as i32) as f64;
        let slack_after_next = (pr - nx).max(0.0) / cap;
        score -= 12.0 * fits_next * (1.0 - slack_after_next * slack_after_next);
        // penalize leaving a gap just below next item size (smooth trough)
        let gap = (pr - nx) / cap;
        if gap > 0.0 && gap < 0.2 {
            score += 25.0 * (0.2 - gap) * (0.2 - gap) * 25.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Many open bins: prefer consolidating into existing bins (penalize new bins implicitly
    // by rewarding bins with residual below mean, i.e., tighter bins)
    let mean_gap = (mean_residual - pr) / cap;
    score -= 6.0 * mean_gap * (1.0 + progress_poly);

    // New-bin candidate: empty bin should score high (undesirable) unless residuals are poor
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score = cap + 10.0 - 20.0 * avg_waste * avg_waste + 10.0 * progress;
    }

    score
}

