pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    // on very small residuals to avoid unusable dead space.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / (bin_capacity as f64);

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chain: post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Near-perfect chain: next item fits with little slack left.
        else if post_residual >= next_item_size {
            let slack = pr - nxt;
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64));
            // Extra reward if the chain continues: residual after next item
            // is tiny (encourage building exact packing sequences).
            let after_next = pr - nxt;
            if after_next <= 10.0 {
                score -= 15.0;
            }
        }
        // Next item does NOT fit: this bin becomes dead space for the next step.
        else {
            // Penalize proportionally to how badly the next item misses.
            let miss = nxt - pr;
            score += 12.0 + 0.5 * miss;
        }
    }

    // Compare against mean residual: bins with residuals far from the mean
    // that we leave small are good (consolidating space).
    if pr < mean_residual {
        score -= 0.25 * (mean_residual - pr);
    } else {
        score += 0.15 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // unattractive unless the item fits poorly everywhere (handled by the
    // large penalties above on open bins with bad fits).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 20.0;
        }
    }

    // Slight preference to keep fewer open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

