    }

    if post_residual > 0 && (post_residual as f64) < cap * 0.25 {
        score += 8.0;
    }
    if post_residual > 10 && post_residual < 20 && next_item_size > post_residual {
        score += 4.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize small dead space that nothing can fill (items >= 1, but realistically >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        score -= 5.0;
        if next_waste == 0 {
            score -= 15.0;
        } else if next_waste < 10 {
            score -= 6.0;
        }
        // Pairing quality scaled by how much slack remains for the pair.
        score -= 3.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item.
        score += 4.0;
    }

    // Last-chance bin: strong incentive to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: open only when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut penalty = 18.0;
        // Early stream: opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= 1.0 + progress;
        // Many open bins with slack: discourage new bins.
        penalty += 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, new bin is wasteful.
        penalty += 0.3 * mean_residual;
        score += penalty;
    } else {
        // Mild preference for reusing fuller bins (smaller residual first).
        score += 0.05 * bin_residual as f64;
    }

    // Late stream: consolidate aggressively into existing bins.
    if progress_late(step_index, total_items) {
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

fn progress_late(step_index: usize, total_items: usize) -> bool {
    total_items > 0 && (step_index as f64 / total_items as f64) > 0.8
}

